// Package router 按「版本 + 业务领域」组织路由。
//
// 约定：
//   - register.go 是聚合入口，只做分组，不写具体接口；
//   - 每个业务领域一个文件（user.go / order.go / product.go），互不干扰；
//   - 新加模块时只改自己领域的文件，避免多人改同一个文件冲突；
//   - 路由只做 URL -> handler 映射，不写业务逻辑。
package router

import (
	"context"

	"hertz-tutorial/demo/biz/middleware"

	"github.com/cloudwego/hertz/pkg/app"
	"github.com/cloudwego/hertz/pkg/app/server"
	"github.com/cloudwego/hertz/pkg/common/utils"
	"github.com/cloudwego/hertz/pkg/protocol/consts"
)

// GeneratedRegister registers routers generated by IDL.
func GeneratedRegister(r *server.Hertz) {
	//INSERT_POINT: DO NOT DELETE THIS LINE!
}

// Register 注册全部手写路由。
// 分组结构：基础设施 / v1 版本组 / 各业务领域。
func Register(r *server.Hertz) {
	// 基础设施接口：健康检查会被高频轮询，不挂访问日志，避免刷屏
	registerSystem(r)

	// v1 版本组：组级中间件统一挂在这里（以后鉴权、限流也加到这个参数里）
	v1 := r.Group("/api/v1", middleware.RequestInfo())

	// 业务领域：每个模块只注册自己的路由
	registerUser(v1)
	registerFile(v1)

	// 兜底路由
	r.NoRoute(func(ctx context.Context, c *app.RequestContext) {
		c.JSON(consts.StatusNotFound, utils.H{"message": "页面找不到啦"})
	})
	r.NoMethod(func(ctx context.Context, c *app.RequestContext) {
		c.JSON(consts.StatusMethodNotAllowed, utils.H{"message": "方法不允许"})
	})
}
